/**
 * Core data types for OpenMascot.
 *
 * Everything in this file is plain, JSON-serialisable data (except the
 * optional procedural `fn` hooks) so characters and animations can be
 * authored by hand, generated by AI, stored, and shipped to other runtimes
 * (e.g. React Native) unchanged.
 */

/** Animatable channels of a bone. All optional; omitted = rest value. */
export interface BoneChannels {
  /** Translation in character units (applied in the parent's space). */
  x: number;
  y: number;
  /** In-plane rotation, degrees, clockwise. */
  rot: number;
  /** Scale about the pivot (1 = rest). */
  sx: number;
  sy: number;
  /** Pseudo-3D turn left/right of this bone's subtree, degrees. */
  yaw: number;
  /** Pseudo-3D nod up/down of this bone's subtree, degrees. */
  pitch: number;
  /** Dolly toward (+) / away (−) from the camera, character units. */
  dz: number;
  /** 0..1, multiplies into children. */
  opacity: number;
}

export type Channel = keyof BoneChannels;

export const CHANNELS: readonly Channel[] = [
  'x',
  'y',
  'rot',
  'sx',
  'sy',
  'yaw',
  'pitch',
  'dz',
  'opacity',
];

/** Rest values. Scales and opacity rest at 1, everything else at 0. */
export const REST: Readonly<BoneChannels> = Object.freeze({
  x: 0,
  y: 0,
  rot: 0,
  sx: 1,
  sy: 1,
  yaw: 0,
  pitch: 0,
  dz: 0,
  opacity: 1,
});

/**
 * A pose: the full animatable state of a character at an instant.
 * Bone channels are stored as *offsets from rest* for x/y/rot/yaw/pitch/dz
 * and as *absolute* values for sx/sy/opacity (rest = 1).
 */
export interface Pose {
  bones: Record<string, Partial<BoneChannels>>;
  /** Character parameters (e.g. `lookX`, `blink`, `breathe`), see {@link ParamDef}. */
  params: Record<string, number>;
  /** Slot → variant overrides. */
  slots: Record<string, string>;
  /** Named expression (resolved to slots by the character). */
  expression?: string;
}

/* ------------------------------------------------------------------ */
/* Rig (compiled character)                                            */
/* ------------------------------------------------------------------ */

export type Surface = 'volume' | 'flat' | 'face' | 'back' | 'feature';

export interface SpringDef {
  stiffness: number;
  damping: number;
  /** Absolute rest position of the spring's centre of mass. */
  tip: [number, number];
  /**
   * Optional `[min, max]` limits (degrees, in the bone's local unmirrored
   * sense: + = clockwise) for the spring's extra rotation
   * (`data-om-spring-limit`). Default ±55°.
   */
  limit?: [number, number];
}

/**
 * A pinned point (`data-om-pin`): the rest point `at` (absolute coordinates)
 * of the pinned bone's art is glued to wherever bone `bone`'s current world
 * transform carries that same rest point.
 */
export interface PinDef {
  bone: string;
  at: [number, number];
}

/** A node of the compiled rig tree. */
export type RigNode = BoneNode | SlotNode | LayerNode | ArtNode;

export interface BoneNode {
  kind: 'bone';
  /** Unique node index (stable, shared numbering with all node kinds). */
  index: number;
  /** Bone-instance index into `Rig.bones` / `Frame.bones`. */
  bi: number;
  name: string;
  pivot: [number, number];
  z: number;
  surface: Surface;
  normal: [number, number];
  spring?: SpringDef;
  shadow?: boolean;
  /**
   * Depth used only for draw-order sorting among siblings (`data-om-sort-z`),
   * in place of `z`. Parallax and perspective still use `z`. Lets a big
   * volume (a head on a body) sort by the surface that actually overlaps its
   * neighbours instead of by its pivot.
   */
  sortZ?: number;
  /**
   * `flat` surfaces only (`data-om-flat-min`): minimum |foreshortening| (0..1).
   * Instead of fading out edge-on, the art keeps this fraction of its width
   * (a wing or ear seen edge-on still reads as a thin shape) and stays opaque.
   */
  flatMin?: number;
  /**
   * `feature` surfaces only (`data-om-feature-min`): how narrow the feature
   * may foreshorten in profile (0..1). Default 0.4; higher keeps snouts and
   * beaks protruding more when the head turns.
   */
  featureMin?: number;
  /**
   * Skin constraint (`data-om-pin`): one to three points of this bone's art
   * pinned to points carried by other bones. One pin rotates + stretches the
   * bone about its pivot; two pins give the exact affine map of the triangle
   * (pivot, pin 1, pin 2); three pins give the affine map of the triangle of
   * pins (the pivot then only follows) — membranes that stay attached to body
   * and limb.
   */
  pin?: PinDef[];
  /** Extra attributes copied from the source `<g>` (minus data-om-*). */
  attrs: Record<string, string>;
  children: RigNode[];
}

export interface SlotNode {
  kind: 'slot';
  index: number;
  name: string;
  z: number;
  defaultVariant: string;
  variants: { name: string; attrs: Record<string, string>; children: RigNode[] }[];
  attrs: Record<string, string>;
}

export interface LayerNode {
  kind: 'layer';
  index: number;
  z: number;
  attrs: Record<string, string>;
  children: RigNode[];
}

/** Static markup, pre-serialised. */
export interface ArtNode {
  kind: 'art';
  index: number;
  markup: string;
}

export interface Rig {
  id: string;
  viewBox: [number, number, number, number];
  /** Root-level `<defs>` markup (gradients, clip paths…). */
  defs: string;
  /** Top level nodes (usually `shadow` and `root`). */
  nodes: RigNode[];
  /** All bone instances, by instance index order. */
  bones: BoneNode[];
  /** Bone name → instances. */
  bonesByName: Record<string, BoneNode[]>;
  slots: SlotNode[];
  slotsByName: Record<string, SlotNode>;
  /** Attributes of the root `<svg>` that should be preserved (minus viewBox/xmlns/data-om-*). */
  svgAttrs: Record<string, string>;
}

/* ------------------------------------------------------------------ */
/* Character definition                                                */
/* ------------------------------------------------------------------ */

/**
 * A parameter is a high-level, character-independent control
 * (`lookX`, `blink`, `wingFlap`…) that drives one or more bone channels.
 * Clips that animate params are portable between characters.
 */
export interface ParamDef {
  /** Default value. */
  default?: number;
  min?: number;
  max?: number;
  /** Bone channel drivers: `value * k` (or piecewise `curve`) is ADDED to the channel. */
  drives: ParamDriver[];
}

export interface ParamDriver {
  bone: string;
  channel: Channel;
  /** Linear gain. */
  k?: number;
  /** Piecewise-linear mapping `[[param, channelDelta], …]` (sorted by param). */
  curve?: [number, number][];
}

export interface CharacterDef {
  id: string;
  name: string;
  /** Annotated SVG source (see docs/rig-format.md). */
  svg: string;
  /** Named expressions: slot → variant maps. `neutral` should exist. */
  expressions: Record<string, Record<string, string>>;
  params?: Record<string, ParamDef>;
  /** Character-specific animation clips (merged over the shared library). */
  clips?: Record<string, Clip>;
  /** Named colours, for recolouring/theming: token → hex used in the SVG. */
  palette?: Record<string, string>;
  /** Bone used as attachment point when an effect says `at: "head"` etc. Defaults to bone names. */
  anchors?: Record<string, { bone: string; offset?: [number, number] }>;
  /** Idle behaviour tuning. */
  idle?: IdleConfig;
  /**
   * Per-effect default params for this character, merged *under* the params
   * of every emission (clip events and `emit()`), e.g.
   * `{ tears: { eyeX: 40, eyeY: -10 } }` so shared clips land on its eyes.
   */
  effectParams?: Record<string, Record<string, unknown>>;
  /** Free-form metadata (author, licence, tags). */
  meta?: Record<string, unknown>;
}

export interface IdleConfig {
  /** Clip played when nothing else is. Default `idle`. */
  clip?: string;
  /** Mean seconds between automatic blinks. Default 3.5. */
  blinkEvery?: number;
  /** Mean seconds between idle fidgets (ear twitch, glance…). 0 disables. Default 6. */
  fidgetEvery?: number;
  /** Clip names used as fidgets. */
  fidgets?: string[];
}

/* ------------------------------------------------------------------ */
/* Animation clips                                                     */
/* ------------------------------------------------------------------ */

export type EaseName =
  | 'linear'
  | 'step'
  | 'in'
  | 'out'
  | 'inOut'
  | 'sineIn'
  | 'sineOut'
  | 'sineInOut'
  | 'quadIn'
  | 'quadOut'
  | 'quadInOut'
  | 'cubicIn'
  | 'cubicOut'
  | 'cubicInOut'
  | 'backIn'
  | 'backOut'
  | 'backInOut'
  | 'elasticOut'
  | 'bounceOut';

/** Easing of the segment *leaving* this keyframe. Name or cubic-bezier control points. */
export type Ease = EaseName | [number, number, number, number];

/** `[time, value]` or `[time, value, ease]`. Ease applies to the segment that starts at this key. */
export type Keyframe = [number, number] | [number, number, Ease];

/** Bone name → channel → keys. */
export type BoneTracks = Record<string, Partial<Record<Channel, Keyframe[]>>>;

export interface EffectEvent {
  /** Time of emission (clip units). */
  t: number;
  /** Effect name from the effect registry (`hearts`, `sparkles`, `notes`…). */
  effect: string;
  /** Bone/anchor name to emit from, or absolute `[x, y]` character coordinates. */
  at?: string | [number, number];
  /** Effect parameters (count, colour, spread…). */
  params?: Record<string, unknown>;
}

export interface Clip {
  /** Clip name (filled in from the registry key if omitted). */
  name?: string;
  /** Human description (shown in the playground, useful for AI authoring). */
  description?: string;
  /** Category for UIs: `idle`, `emotion`, `dance`, `gesture`, `pose`, `locomotion`, `fidget`. */
  category?: string;
  /** Length in clip time units. */
  duration: number;
  /** Clip time unit. With `beats`, times are in beats and `bpm` sets speed. Default `seconds`. */
  units?: 'seconds' | 'beats';
  /** Tempo for `beats` clips. Default 120. */
  bpm?: number;
  /** Loop by default when played. */
  loop?: boolean;
  /** Bone keyframe tracks. */
  bones?: BoneTracks;
  /** Param keyframe tracks. */
  params?: Record<string, Keyframe[]>;
  /** Expression changes (step): `[time, expressionName]`. */
  expression?: [number, string][];
  /** Slot variant changes (step): slot → `[time, variant]`. */
  slots?: Record<string, [number, string][]>;
  /** Effect emissions. */
  events?: EffectEvent[];
  /**
   * Procedural layer evaluated on top of the keyframes (additive for
   * offset channels, multiplicative for sx/sy/opacity). `t` is in clip units.
   */
  fn?: (t: number, out: Pose, ctx: ClipContext) => void;
  /** Disable runtime idle layers while this clip is dominant. */
  suppress?: { blink?: boolean; breathe?: boolean; look?: boolean; fidget?: boolean };
  /** Seconds of crossfade used when transitioning *into* this clip (default 0.25). */
  fadeIn?: number;
  /** One-shots: clip that follows by default (`null` = hold the last frame). Default: the idle clip. */
  then?: string | null;
  /** Shadow opacity multiplier while this clip plays (0 for hanging/peeking poses). Default 1. */
  shadow?: number;
  /** Hide eye-art swaps behind an automatic blink. Default true. */
  blinkMask?: boolean;
}

export interface ClipContext {
  /** Clip duration (clip units). */
  duration: number;
  /** Seconds per clip unit. */
  secondsPerUnit: number;
  /** Deterministic random in [0,1) seeded per playback. */
  random: () => number;
}

/* ------------------------------------------------------------------ */
/* Solved frame                                                        */
/* ------------------------------------------------------------------ */

/** 2D affine matrix `[a, b, c, d, e, f]` (SVG `matrix()` order). */
export type Mat = [number, number, number, number, number, number];

export interface SolvedBone {
  /** Local transform relative to the parent group. */
  local: Mat;
  /** World transform (character space). */
  world: Mat;
  opacity: number;
  /** Projected depth (world). */
  depth: number;
  /** Accumulated yaw/pitch (deg) of this bone — useful for effects & debugging. */
  yaw: number;
  pitch: number;
  /** For spring bones: world transform *without* the spring rotation (drives the simulation). */
  rigid?: Mat;
}

/** A frame is everything a renderer needs to draw the character at an instant. */
export interface Frame {
  /** Per bone *instance* (indexed by BoneNode.index). */
  bones: SolvedBone[];
  /** Slot name → visible variant. */
  slots: Record<string, string>;
  /**
   * Container node index (`-1` for the top level) → render order of its
   * children (indices into that container's `children` array). For slots the
   * key is the index of the slot node and the order applies to the visible
   * variant's children. Containers whose order equals document order may be
   * omitted.
   */
  order: Map<number, number[]>;
}
